-- Secondary school verification (REMEDIATION_PLAN.md Phase 1E, 2), 2026-11-22.
-- Strict rule: a school is published only if a Wikipedia article / Wikidata item
-- with the same name describes a school in Nigeria at the record's location.
-- Every accepted match was also reviewed by hand. Facts are set only from those
-- sources; unsourced seed claims and all copied descriptions are cleared.
-- Originals are preserved on the Neon branch pre-remediation-2026-11-21.

-- 1. All schools: remove copied/unsourced descriptive content.
UPDATE schools SET enriched_history = NULL, enriched_academics = NULL, enriched_campus_info = NULL, enriched_student_life = NULL, enriched_notable_alumni = '[]'::jsonb, enriched_recent_news = '[]'::jsonb, content_sources = '[]'::jsonb, template_summary = NULL, ai_summary = NULL, meta_title = NULL, meta_description = NULL, curriculum = NULL, levels = NULL, fee_range = NULL, principal_name = NULL, principal_title = NULL, boarding = NULL, day_school = NULL, gender = NULL, updated_at = NOW() WHERE institution_category = 'school';

-- 2. Duplicates: retire and redirect to the surviving record.
